        top.children["PC_MENU_ENTRY_SKILLS"] = &skills; top.children["PC_MENU_ENTRY_PHOTOJOURNAL"] = &photo;
        Manager m; m.make["UI_MOUSE_POINTER"] = &mouse; m.make["PC_TOP_LEVEL_LIST"] = &top;
        Hero h; h.fireball = 0; h.abilities = true;
